SELECT A.COL1, B.COL2
FROM   A LEFT OUTER JOIN B
ON     (A.COL1 = B.COL1 AND B.COL2 > 200);

SELECT A.COL1
FROM   A
WHERE  NOT EXISTS (SELECT 1 FROM B WHERE A.COL1 = B.COL1);

SELECT A.COL1
FROM   A
WHERE  A.COL1 NOT IN (SELECT B.COL1 FROM B);

SELECT ID
FROM   T
ORDER  BY C1, C2 DESC, C3 NULLS LAST;

CREATE TABLE 부서 (
  부서번호 NUMBER PRIMARY KEY
);
CREATE TABLE 사원 (
  사번     NUMBER PRIMARY KEY,
  부서번호 NUMBER REFERENCES 부서
           ON DELETE SET NULL
);
CREATE TABLE 프로젝트 (
  번호     NUMBER PRIMARY KEY,
  부서번호 NUMBER REFERENCES 부서
           ON DELETE CASCADE
);

